shellCommands.command:
rm -rf dist && cat > /tmp/cpu_mock_check.mjs <<'EOF'
const {createMockCpuSource} = await import('/home/sandbox/workspace/src/cpu/mockCpuSource.ts');
const src = createMockCpuSource();
const win = src.snapshot();
const n = win.timeline.length;
let okStep = true, okRange = true;
for (let i = 1; i < n; i++) {
  if (win.timeline[i] - win.timeline[i - 1] !== 2000) okStep = false;
}
for (const v of win.values) if (v < 0 || v > 100 || Number.isNaN(v)) okRange = false;
console.log({points: n, span_h: (win.timeline[n-1]-win.timeline[0])/3600000, okStep, okRange, lastIsAligned: win.timeline[n-1] % 2000 === 0});
let received = 0;
let last = null;
const unsub = src.subscribe((s) => { received++; last = s; });
await new Promise((r) => setTimeout(r, 4100));
console.log({received_in_4s: received, sampleStepOk: last && last.time > win.timeline[n-1]});
unsub();
// With no listeners the interval must be cleared: the process should exit on its own.
console.log('unsubscribed; event loop should drain');
EOF
timeout 20 node /tmp/cpu_mock_check.mjs; echo "exit=$?"
